"use client";

import { useEffect, useState } from "react";
import type { ImageCreditData } from "@/components/image-credit";
import type { LightboxImage } from "@/components/ui/lightbox";
import type { Locale } from "@/lib/i18n";
import { siteLabel, type Site } from "./sites";

// data/gallery.json is generated by scripts/fetch-site-gallery.mjs: more
// photos of each site, keyed by site id. It is loaded only once a dig is over
// (the photos would give the answer away), and in a chunk of its own so it
// never weighs on the game itself.

export type GalleryPhoto = {
  src: string;
  width: number;
  height: number;
  credit: ImageCreditData;
  /** A short description from Commons, in English and/or Portuguese. */
  caption?: { en?: string; pt?: string };
};

type Gallery = Record<string, GalleryPhoto[]>;

let loading: Promise<Gallery> | null = null;

function loadGallery(): Promise<Gallery> {
  loading ??= import("./data/gallery.json").then(
    (module) => module.default as Gallery,
    (err) => {
      loading = null;
      throw err;
    },
  );
  return loading;
}

/** A site's extra photos once `enabled` (an empty list until then, or if they fail to load). */
export function useGallery(siteId: string, enabled: boolean): GalleryPhoto[] {
  const [loaded, setLoaded] = useState<{ id: string; photos: GalleryPhoto[] } | null>(null);
  useEffect(() => {
    if (!enabled) return;
    let live = true;
    loadGallery().then(
      (gallery) => live && setLoaded({ id: siteId, photos: gallery[siteId] ?? [] }),
      () => {},
    );
    return () => {
      live = false;
    };
  }, [siteId, enabled]);
  return enabled && loaded?.id === siteId ? loaded.photos : [];
}

/**
 * The main photo, then the gallery's, as the lightbox shows them. `untitled`
 * names a photo that has no caption: "Petra, photo 3".
 */
export function lightboxImages(
  site: Site,
  photos: GalleryPhoto[],
  locale: Locale,
  untitled: (n: number) => string,
): LightboxImage[] {
  const name = siteLabel(site, locale);
  const other: Locale = locale === "pt" ? "en" : "pt";
  return [
    { ...site.image, alt: name, caption: name },
    ...photos.map((photo, i): LightboxImage => {
      const own = photo.caption?.[locale];
      const fallback = photo.caption?.[other];
      const caption = own ?? fallback;
      return {
        src: photo.src,
        width: photo.width,
        height: photo.height,
        credit: photo.credit,
        alt: caption ? `${site.name[locale]}: ${caption}` : untitled(i + 2),
        caption,
        captionLang: !own && fallback ? other : undefined,
      };
    }),
  ];
}
